+alert http any any -> any any (
+    msg:"Custom telemetry exfil pattern";
+    flow:to_server,established;
+    http.method; content:"POST"; nocase;
+    http.uri; pcre:"/^\\/telemetry\\/v2\\/report$/";
+    http.uri; content:"/telemetry/v2/report"; nocase; fast_pattern;
+    http.header; pcre:"/\\r?\\nX-TLM-Mode\\s*:\\s*exfil\\r?\\n/i";
+    http.request_body; pcre:"/blob=[A-Za-z0-9+\\/=]{80,}/";
+    http.request_body; pcre:"/sig=[A-Fa-f0-9]{64}/";
+    sid:1000001; rev:1;
+)
